package com.entitlerhq.examples.generatedfeatures

import com.entitlerhq.entitler.EntitlerServer
import com.entitlerhq.entitler.Feature
import kotlinx.coroutines.runBlocking

/** Checks features through constants generated by entitler generate. Run it with ENTITLER_KEY set. */
fun main(): Unit =
    runBlocking {
        EntitlerServer(System.getenv("ENTITLER_KEY")).use { entitler ->
            val customer = entitler.customer("generated-features-customer")
            customer.register(name = "Dorothy Vaughan")

            val credits = customer.check(Features.aiCredits)
            println("AI credits: ${credits.used} used, ${credits.remaining} left.")
            for (feature in listOf<Feature>(Features.exportPdf, Features.collaboration, Features.teamSeats)) {
                println("${feature.key}: ${customer.isEntitled(feature)}")
            }
        }
    }
